test("lead-time demand is average daily sales multiplied by supplier lead time in days", function () {
  var result = code.reorderCheck({ averageDailySales: 50, leadTimeDays: 6, stockOnHand: 360 });
  assert.equal(result.leadTimeDemand, 300);
});

test("safety stock is 20 percent of lead-time demand", function () {
  var result = code.reorderCheck({ averageDailySales: 50, leadTimeDays: 6, stockOnHand: 360 });
  assert.equal(result.leadTimeDemand, 300);
  assert.equal(result.safetyStock, 60);
});

test("reorder point is lead-time demand plus safety stock", function () {
  var result = code.reorderCheck({ averageDailySales: 50, leadTimeDays: 6, stockOnHand: 360 });
  assert.equal(result.leadTimeDemand, 300);
  assert.equal(result.safetyStock, 60);
  assert.equal(result.reorderPoint, result.leadTimeDemand + result.safetyStock);
  assert.equal(result.reorderPoint, 360);
});

test("reorder point equals 1.2 times lead-time demand", function () {
  var result = code.reorderCheck({ averageDailySales: 50, leadTimeDays: 6, stockOnHand: 360 });
  assert.equal(result.leadTimeDemand, 300);
  assert.equal(result.reorderPoint, 1.2 * result.leadTimeDemand);
  assert.equal(result.reorderPoint, 360);
});

test("recommend a reorder when stock on hand is at the reorder point", function () {
  var result = code.reorderCheck({ averageDailySales: 50, leadTimeDays: 6, stockOnHand: 360 });
  assert.equal(result.reorderPoint, 360);
  assert.equal(result.reorder, true);
});

test("do not recommend a reorder when stock on hand is above the reorder point", function () {
  var result = code.reorderCheck({ averageDailySales: 50, leadTimeDays: 6, stockOnHand: 361 });
  assert.equal(result.reorderPoint, 360);
  assert.equal(result.reorder, false);
});
